import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"蹇","description":"焦氏易林注 - 蹇","frontmatter":{"title":"蹇","description":"焦氏易林注 - 蹇"},"headers":[],"relativePath":"zh/classics/jiaoyilin/039.md","filePath":"zh/classics/jiaoyilin/039.md"}'),l={name:"zh/classics/jiaoyilin/039.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h3 id="蹇-1" tabindex="-1">蹇 <a class="header-anchor" href="#蹇-1" aria-label="Permalink to “蹇”">​</a></h3><h3 id="蹇之乾" tabindex="-1">蹇之乾 <a class="header-anchor" href="#蹇之乾" aria-label="Permalink to “蹇之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>叔肸居冤，祁子自邑。乘遽解患，羊舌脫免，賴得生全。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>肸，叔向名也。《左傳襄二十一年》：欒盈之亂，範宣子殺羊舌虎，虎叔向弟，故囚叔向。大夫祁奚聞之，乘馹而見宣子，救叔向，免之。遽即馹。僖三十三年，且使遽告於鄭。註：傳車，即驛遞也，此似用遇卦象。蹇下艮為叔、為邑，坎為車，重坎故曰遽。遽，傳車至驛而更有類，重坎象。坎為患，兌為羊、為舌，兌伏故曰脫免。○肸居，宋元本作盻拘，依汲古。脫免，宋本、汲古作免脫，依元本校協。</p><h3 id="蹇之坤" tabindex="-1">蹇之坤 <a class="header-anchor" href="#蹇之坤" aria-label="Permalink to “蹇之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>兔聚東郭，眾犬俱獵。圍缺不成，無所能獲。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍兼用遇卦象。坎為眾，離位東，艮為郭、為犬，坎為眾，坤為圍，中斷故圍缺。震為兔，茲無震象，疑用艮。《戰國策》&quot;東郭●，宋之狡兔也&quot;。</p><h3 id="蹇之屯" tabindex="-1">蹇之屯 <a class="header-anchor" href="#蹇之屯" aria-label="Permalink to “蹇之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>作室山根，人以為安。一夕崩顛，敗我壺餐。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為室、為山，震為人，艮為安。坎為夕，數一，故曰一夕。震為覆艮，故曰山崩。坤為壺、為漿、為我，坎破故曰敗。○顛，宋元本作頹，壺作盤，依汲古。</p><h3 id="蹇之蒙" tabindex="-1">蹇之蒙 <a class="header-anchor" href="#蹇之蒙" aria-label="Permalink to “蹇之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>疾風塵起，亂擾崩始。強大並小，先否後喜。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為風、為疾，艮為塵，震為起，坤為亂擾，二四艮覆故曰崩。震為始，言亂自此始也。震為強大，正反震，中互坤，坤小故曰強大並小。坎陷故曰否。震為喜、為後，故曰先否後喜。○擾，汲古作我，依宋元本。始，疑為殆，殆，古音以，亦葉。</p><h3 id="蹇之需" tabindex="-1">蹇之需 <a class="header-anchor" href="#蹇之需" aria-label="Permalink to “蹇之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>潔齊沐浴，思明君德。哀公怯弱，風氏復北。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>《論語》：&quot;陳成子弒簡公，孔子沐浴而朝，請討之&quot;。坎為水，故曰潔、曰沐浴。乾為君，互離為明。思明君德者，言宜討齊以明君臣之分也。乾為公，坎為憂哀、為怯，風疑為薑。巽為薑，二至四巽覆，故曰薑氏復北。北，敗也。坎為北，言公不從孔子之請，薑氏自此滅也。丁晏等以風氏指顓臾季氏伐之為解，似非。○君，汲古作不，非，依宋元本。</p><h3 id="蹇之訟" tabindex="-1">蹇之訟 <a class="header-anchor" href="#蹇之訟" aria-label="Permalink to “蹇之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>土痟瘦薄，培塿無柏，使我不樂。通《明夷》。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坤土，坎為薄，震為陵，故曰培塿。艮為木、為堅，故為柏，艮覆故無柏。震為樂，坎憂故不樂。</p><h3 id="蹇之師" tabindex="-1">蹇之師 <a class="header-anchor" href="#蹇之師" aria-label="Permalink to “蹇之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>褰衣涉河，水深漬罷。賴遇舟子，濟脫無他。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>第二句汲古作澗流渦多，依宋元本。罷，音婆，詳《訟》之《萃》。</p><h3 id="蹇之比" tabindex="-1">蹇之比 <a class="header-anchor" href="#蹇之比" aria-label="Permalink to “蹇之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>送我季女，至於盪道。齊子旦夕，留連久處。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《大過》。</p><h3 id="蹇之小畜" tabindex="-1">蹇之小畜 <a class="header-anchor" href="#蹇之小畜" aria-label="Permalink to “蹇之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>三孫六子，安無所苦。中歲廢殆，亡我所使。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。艮為孫，數三，故曰三孫。震為子，坎數六，故曰六子。艮為安，坎為勞苦、為中，坤為歲、為喪，故曰廢殆。坤又為亡、為我。○歲，汲古作藏，依宋元本。廢，宋元本訛發，依汲古。</p><h3 id="蹇之履" tabindex="-1">蹇之履 <a class="header-anchor" href="#蹇之履" aria-label="Permalink to “蹇之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>揚風偃草，塵埃俱起。清濁溷散，忠直隱處。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>互巽為風、為草，巽為伏，故曰偃伏。艮為塵，埃伏，坎為水而與土連，故曰濁、曰溷。清濁溷散，言清濁不分也。坎為忠，乾為直，坎為隱。○首句元本作偃風掦草，依宋本、汲古。</p><h3 id="蹇之泰" tabindex="-1">蹇之泰 <a class="header-anchor" href="#蹇之泰" aria-label="Permalink to “蹇之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>履險登危，道遠勞罷。去家自歸，困涉大波。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>兌折故危險，震為足，故曰履、曰登。震為道，坤役萬物故勞疲。伏艮為家，震為歸、為涉，坤水乾大，故曰大波。○去家，宋本作玄家，元本作元豕，依汲古。</p><h3 id="蹇之否" tabindex="-1">蹇之否 <a class="header-anchor" href="#蹇之否" aria-label="Permalink to “蹇之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>六藝之門，仁義俱存。鎡基逢時，堯舜為君。傷寒溫，下至黃泉。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為門，數六，故曰六藝之門。六藝，六經也。乾仁坤義，艮為時，乾為堯舜、為君、為寒，艮火故曰溫。坤為水、為泉、為下，坤死，故下至黃泉。鎡基，《孟子》趙岐註：耒耜也。伏震象。五六二句與上意不屬，似為他林溷入者。</p><h3 id="蹇之同人" tabindex="-1">蹇之同人 <a class="header-anchor" href="#蹇之同人" aria-label="Permalink to “蹇之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>被服文衣，游觀酒池。上堂見觴，喜為吾兄，使我憂亡。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為衣，離為文，故被服文衣。伏震為游，離為觀，伏坎為酒池，故游觀酒池。震為觴、為喜、為兄，伏坤為我、為憂、為亡。</p><h3 id="蹇之大有" tabindex="-1">蹇之大有 <a class="header-anchor" href="#蹇之大有" aria-label="Permalink to “蹇之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>生時不利，天命災至。制於斧瘢，晝夜勤苦。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>伏艮為時，巽為利、為命，巽覆故不利，故災至。乾為天，坤為災也。伏坎為制，兌為斧，艮多節，故曰斧瘢。離晝坎夜，坎勞故勤苦。</p><h3 id="蹇之謙" tabindex="-1">蹇之謙 <a class="header-anchor" href="#蹇之謙" aria-label="Permalink to “蹇之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>天門開闢，牢戶寥闊。桎梏解脫，拘囚縱釋。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>《內經》以戌亥為天門，艮先天居戌亥，故曰天門。坤為門戶也。坎為牢、為桎梏，震解故脫。坎為拘囚，震縱釋。</p><h3 id="蹇之豫" tabindex="-1">蹇之豫 <a class="header-anchor" href="#蹇之豫" aria-label="Permalink to “蹇之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>川原難游，水為我憂。多言少實，命鹿為駒。建德開基，君子逢時，利以中疑。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坤為川原，坎陷故難游。震為言，正反震，坤虛故少實。震為鹿，亦為馬，故曰命鹿為駒。命，名也。《史記》秦趙高命鹿為馬。艮為名、為君子、為時，伏巽為利，坎為疑、為中，林文疑祇四句而止，後三句皆他人林文羼入者。○建，汲古作道，依宋元本。中，宋元本作仲，依汲古。</p><h3 id="蹇之隨" tabindex="-1">蹇之隨 <a class="header-anchor" href="#蹇之隨" aria-label="Permalink to “蹇之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>鄉歲逢時，與生為期。枝葉盛茂，君子無憂。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為歲，艮為時，震為生、為枝葉、為茂盛，艮為君子，震喜兌悅故無憂。</p><h3 id="蹇之蠱" tabindex="-1">蹇之蠱 <a class="header-anchor" href="#蹇之蠱" aria-label="Permalink to “蹇之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>六鷁退飛，為襄敗祥。陳師合戰，左股夷傷。遂崩不起，霸功不成。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖十六年》：&quot;六鷁退飛，過宋都，周內史叔興對襄公曰：君將得諸侯而不終。後二十一年，楚人執宋公，二十二年，宋敗於泓，襄公傷左股，遂卒。&quot;故曰為襄敗徵。艮為鷁，震反故曰退飛。震為諸侯，故曰襄公，兌折故敗。祥猶徵也。震為陳，坎為眾，互大坎故曰陳師。巽為股，震為戰、為左，兌折故傷。三至五艮覆故曰崩。震為霸、為功，四至上震覆，故霸功不成。○襄敗，宋元本作衰敗，汲古作衰殷，皆非。依《旅》之《萃》校。</p><h3 id="蹇之臨" tabindex="-1">蹇之臨 <a class="header-anchor" href="#蹇之臨" aria-label="Permalink to “蹇之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>雷君出裝，隱隱西行。霖雨不止，流為河江，南國以傷。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為雷、為君、為出，故曰雷君出裝。雷君，即雷師也。兌為西、為雨，坤為水、為江河、為國，震為南，故曰南國。兌為傷。○河，宋元本作巨，依汲古。以傷，汲古作凶憂，依宋元本。</p><h3 id="蹇之觀" tabindex="-1">蹇之觀 <a class="header-anchor" href="#蹇之觀" aria-label="Permalink to “蹇之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>牙孽生達，室蟠啟戶。幽人利貞，鼓翼起舞。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。震為芽孽、為生，艮為室，坤為戶。蟠，曲也，屈也，言室宇曲屈而啟戶也。震為啟，艮為高尚、為幽人，巽為利、為伏，故曰利貞。震為鼓、為翼、為起、為舞。○汲古林詞與《小畜》之《睽》同，依宋元本。</p><h3 id="蹇之噬嗑" tabindex="-1">蹇之噬嗑 <a class="header-anchor" href="#蹇之噬嗑" aria-label="Permalink to “蹇之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>火起上門，不為我殘。跳脫東西，獨得生完。不利出鄰，病疾憂患。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離火在艮門上，故不為患。震為跳脫，離東坎西故跳脫東西。震為鄰、為出，然出即與坎逢而疾病，故不利也。○上，汲古訛土，依宋本。</p><h3 id="蹇之賁" tabindex="-1">蹇之賁 <a class="header-anchor" href="#蹇之賁" aria-label="Permalink to “蹇之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>舉事無成，不利出征。言不可用，眾莫能平。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為舉，正反震故無成，故不利出征，故言不可用。坎為平、為眾。○莫，汲古作不，依宋元本。</p><h3 id="蹇之剝" tabindex="-1">蹇之剝 <a class="header-anchor" href="#蹇之剝" aria-label="Permalink to “蹇之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>老狼白獹，長尾大胡。前顛卻躓，進退遇祟。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《需》。獹、胡原作驢、狐，驢，獹之形訛字。狐，胡之音訛字，並依《震》之《恆》校。</p><h3 id="蹇之復" tabindex="-1">蹇之復 <a class="header-anchor" href="#蹇之復" aria-label="Permalink to “蹇之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>日入道極，勞者休息。班馬還師，復我燕室。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用《蹇》象。坎為暮，離在坎下故曰日入。艮為道。極，盡也，言道止於此也。坎為勞，艮止故休息。坎為馬，重坎故曰班馬，坎眾故曰師，艮止故曰還師。坎為室，伏兌故曰燕室。</p><h3 id="蹇之無妄" tabindex="-1">蹇之無妄 <a class="header-anchor" href="#蹇之無妄" aria-label="Permalink to “蹇之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>林麓山藪，非人所處。鳥獸無禮，使我心苦。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為林、為藪，艮為山、為麓，乾為人，在上故不處山林。艮為鳥、為獸，坤為禮，坤伏故曰無禮。伏坤為我、為心。○首句依宋元本，汲古作山林麓藪。第三句疑。</p><h3 id="蹇之大畜" tabindex="-1">蹇之大畜 <a class="header-anchor" href="#蹇之大畜" aria-label="Permalink to “蹇之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>蓄利積福，日新其德。高氏飲食，憂不為患。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>乾為福，伏巽為利，艮止在上故曰蓄積。艮為日、為高，兌口為飲食，故曰高氏飲食。坤為憂患，坤伏故不憂。</p><h3 id="蹇之頤" tabindex="-1">蹇之頤 <a class="header-anchor" href="#蹇之頤" aria-label="Permalink to “蹇之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>張羅百目，鳥不得北。縮頸掛翼，困於窘國。君子治德，獲譽受福。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>離為目、為網羅，大離故曰百目，坤為百也。坤先天位北，震為鳥，艮止在上故不得北。艮為頸，震為翼，坤退而閉，故縮頸，震反在上故掛翼。艮為國，坤閉故曰窘國。艮為君子、為名譽，震為福，艮為獲，故獲譽。坤受，故受福。</p><h3 id="蹇之大過" tabindex="-1">蹇之大過 <a class="header-anchor" href="#蹇之大過" aria-label="Permalink to “蹇之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>伯虎仲熊，德義淵宏。使布五教，陰陽順序。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏艮為虎熊，震為伯，坎為仲，卦本大坎也。乾為德，伏坤為義、為淵，故曰淵宏。巽卦數五，又為命令，故曰使布五教。乾陽坤陰，巽順，伯虎仲熊，高辛子，八愷之二。</p><h3 id="蹇之坎" tabindex="-1">蹇之坎 <a class="header-anchor" href="#蹇之坎" aria-label="Permalink to “蹇之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《歸妹》。</p><h3 id="蹇之離" tabindex="-1">蹇之離 <a class="header-anchor" href="#蹇之離" aria-label="Permalink to “蹇之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>嬴氏違良，使孟尋兵。老師不已，敗於齊卿。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互兌為西，故曰嬴氏。艮為良，艮伏故曰違良。伏震為孟，艮為兵，坎為眾、為師，重坎故曰老師不已。兌為敗，巽為齊。齊卿，言孟明視、西乞術、白乙丙，皆卿爵。案：《漢書食貨志》：&quot;世家子弟富人或走狗馬博戲，亂齊民。&quot;如淳註：齊，等也，言無貴賤。又《詩召南》：&quot;齊侯之子&quot;，齊侯，猶通侯，即諸侯也，由此證敗於齊卿即敗於諸卿也。《左傳僖三十二年》：&quot;秦穆公違蹇叔諫，使孟明等伐鄭，敗於崤函&quot;。○老師，宋元本作師老，依汲古。</p><h3 id="蹇之咸" tabindex="-1">蹇之咸 <a class="header-anchor" href="#蹇之咸" aria-label="Permalink to “蹇之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>日月並居，常暗且微。高山崩顛，丘陵為溪。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌月艮日，故曰並居。兌為暗昧故曰暗微也。艮為高山，兌毀巽隕，故崩顛。艮為丘陵，兌為溪。○崩，宋本誤萌，依元本、汲古。溪，依宋元本，汲古作溪。</p><h3 id="蹇之恒" tabindex="-1">蹇之恒 <a class="header-anchor" href="#蹇之恒" aria-label="Permalink to “蹇之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>鳥雀食榖，張口受哺。蒙被恩德，長大成就。柔順利貞，君臣合好。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為鳥雀、為谷，兌為口，故曰食谷，曰受哺。乾為大，巽為順、為利，乾君伏坤為臣，六爻皆有應，故曰合好。○被恩，汲古作恩被，依宋元本。</p><h3 id="蹇之遯" tabindex="-1">蹇之遯 <a class="header-anchor" href="#蹇之遯" aria-label="Permalink to “蹇之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>雖躓復起，不毀牙齒。克免平復，憂除無疾。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。兌毀折故曰躓。震為起，兌為牙齒，坤為憂、為疾，震解故除。</p><h3 id="蹇之大壯" tabindex="-1">蹇之大壯 <a class="header-anchor" href="#蹇之大壯" aria-label="Permalink to “蹇之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>草木黃落，歲暮無室。虐政為賊，大人失福。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。候卦為八月，巽為草木、為隕落，坤黃故曰黃落。候卦坤居亥，故曰歲暮。艮為室，巽隕故無室。坤為政，巽為賊，乾為大人。壯，傷也，故失福。</p><h3 id="蹇之晉" tabindex="-1">蹇之晉 <a class="header-anchor" href="#蹇之晉" aria-label="Permalink to “蹇之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>避凶東走，反入禍口。制於牙爪，骨為灰土。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為凶，離位東，在外，故曰避凶東走。坤為禍，伏兌為口、為牙爪、為骨骸，坤為土，艮火離火，故曰灰土。</p><h3 id="蹇之明夷" tabindex="-1">蹇之明夷 <a class="header-anchor" href="#蹇之明夷" aria-label="Permalink to “蹇之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>欲飛不能，志苦心勞，福不我求。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>離為飛，坎陷故不能飛。坎為心志、為勞苦。○求，依宋元本，汲古作來。</p><h3 id="蹇之家人" tabindex="-1">蹇之家人 <a class="header-anchor" href="#蹇之家人" aria-label="Permalink to “蹇之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>羔裘豹袪，東與福遇。駕迎吾兄，送我驪黃。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>疑用半象。驪，從元本，餘多訛鸝。</p><h3 id="蹇之睽" tabindex="-1">蹇之睽 <a class="header-anchor" href="#蹇之睽" aria-label="Permalink to “蹇之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>東耕破犁，西失良妻。災害不避，家貧無資。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>離為東，兌為西，坎為災害。</p><h3 id="蹇之蹇" tabindex="-1">蹇之蹇 <a class="header-anchor" href="#蹇之蹇" aria-label="Permalink to “蹇之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>同載共輿，中道別去。喪我元夫，獨與孤居。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎為輿，重坎故曰同載共輿。艮為道，坎為中，坎死故別去。震為夫、為元，震覆，故曰喪我元夫。坎為孤，艮為獨，故曰獨與孤居。</p><h3 id="蹇之解" tabindex="-1">蹇之解 <a class="header-anchor" href="#蹇之解" aria-label="Permalink to “蹇之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>魚陸失所，鳧鼃困苦。澤無雈蒲，晉國以虛。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>伏巽為魚，震為鳧，鼃坎為困。</p><h3 id="蹇之損" tabindex="-1">蹇之損 <a class="header-anchor" href="#蹇之損" aria-label="Permalink to “蹇之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>脫兔無蹄，三步五罷。南行不進，後市勞苦。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為兔、為蹄，《莊子》&quot;得兔而忘蹄&quot;註：蹄，兔罥也，系其腳故曰蹄，坤亡故無蹄。震數三，故曰三步，伏巽，卦數五，坤乏，故曰五罷。震為南，艮止，故行不進。伏巽為市，坤勞苦。○兔，元本訛足，依宋本、汲古。勞，宋元本作身，依汲古。</p><h3 id="蹇之益" tabindex="-1">蹇之益 <a class="header-anchor" href="#蹇之益" aria-label="Permalink to “蹇之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>行役未已，新事復起。姬薑勞苦，不得休止。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震行坤役，震為姬，巽為薑，坤為勞苦，艮止故曰休止，正反艮故不得休止。</p><h3 id="蹇之夬" tabindex="-1">蹇之夬 <a class="header-anchor" href="#蹇之夬" aria-label="Permalink to “蹇之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>白日楊光，火為正王。消金厭兵，雷車避藏。陰雨不行，民安其鄉。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮為日、為光、為火，乾為王、為金，艮為兵戈，陰消陽故曰消金厭兵。震為雷、為車，震覆故曰避藏。兌為雨，坤為民、為鄉，艮日在上故陰雨不行而民得安也。○白，宋本、汲古皆作向，依元本。</p><h3 id="蹇之姤" tabindex="-1">蹇之姤 <a class="header-anchor" href="#蹇之姤" aria-label="Permalink to “蹇之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>放銜垂轡，奔馬不制。棄法作姦，君失其位。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為銜、為轡、為奔馬，陽遇陰則通，故曰奔馬不制。坤為姦，震為君，坤為喪，故失位。</p><h3 id="蹇之萃" tabindex="-1">蹇之萃 <a class="header-anchor" href="#蹇之萃" aria-label="Permalink to “蹇之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>司命下游，喜解我憂。皇母緩帶，嬰兒笑喜。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>巽為命，《禮記》：&quot;大夫祭五祀&quot;註：五祀：一曰司命。《漢書天文志》：&quot;近魁六星，四曰司命&quot;。《晉書天文志》：&quot;司命主壽&quot;。互艮為星，故曰司命下游，主壽故解憂，兌悅故喜。坤為母，伏乾故曰皇母。巽為帶，兌為嬰兒，兌悅故笑喜。○兒，宋元本作子，依汲古。</p><h3 id="蹇之升" tabindex="-1">蹇之升 <a class="header-anchor" href="#蹇之升" aria-label="Permalink to “蹇之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>黃帝出游，駕龍乘馬。東上泰山，南過齊魯，邦國咸喜。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為帝，坤土色黃，故曰黃帝。震為龍、為馬、為東，伏艮為山，故東上太山。震又為南，巽齊兌魯，故曰南過齊魯。坤為邦國，震樂兌悅，故曰咸喜。○邦，宋本、汲古作郡，依元本。</p><h3 id="蹇之困" tabindex="-1">蹇之困 <a class="header-anchor" href="#蹇之困" aria-label="Permalink to “蹇之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>既往不說，憂來禍結。比戶為患，無所申雪。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎為憂患，坎陷故禍結。伏艮為戶，正反艮相對，故曰比戶，下與坎連，故曰比戶為患。比戶，近鄰也。近鄰為患，防禦難，故曰無所申雪。○雪，汲古作冤，以與患韻，今依宋元本，雪結為韻。</p><h3 id="蹇之井" tabindex="-1">蹇之井 <a class="header-anchor" href="#蹇之井" aria-label="Permalink to “蹇之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>何蕢隱居，以避亂傾。終身不仕，遂其潔清。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。艮為何，震為蕢，坎隱伏故曰避亂。離為亂也。艮為終、為身、為仕，坎隱故不仕。坎水故曰潔清。</p><h3 id="蹇之革" tabindex="-1">蹇之革 <a class="header-anchor" href="#蹇之革" aria-label="Permalink to “蹇之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>折梃舂稷，君不得食。頭癢搔跟，無益於疾。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>兌為折，巽為梃、為稷，伏艮手故曰春。《孟子》&quot;殺人以梃&quot;趙岐註：梃，杖也，舂米須用槌，今以梃舂，非器。乾為君，兌為食，二至上大過，大過死，故不得食。伏艮為頭，震為跟，坤為疾，故曰癢。正反震艮，故曰頭癢搔跟。搔不得所，與以梃舂稷無功同也。○梃，各本皆作挺，形訛字。孟子梃亦多訛挺，然唐本皆作梃，見阮校。</p><h3 id="蹇之鼎" tabindex="-1">蹇之鼎 <a class="header-anchor" href="#蹇之鼎" aria-label="Permalink to “蹇之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>植根不固，華葉落去，便為枯樹。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>巽下腐，故曰植根不固。兌為華，巽為落、為枯、為樹。</p><h3 id="蹇之震" tabindex="-1">蹇之震 <a class="header-anchor" href="#蹇之震" aria-label="Permalink to “蹇之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>凶門生患，牢戶多冤。沙池禿齒，使叔困貧。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為門，坎陷故曰凶門。坎為獄，故曰牢戶，坎為憂患，故曰多冤。艮為沙，伏兌為齒，巽為寡髪，故曰禿齒。艮為叔，坎為困。○患，汲古作意，池作陁，叔作我，貧作窮，均依宋元本。沙池，即差池，古通用，言齒差池不齊，正以狀貧困之貌，若作沙陁，何以與下句相屬，且禿齒亦無此國名，故陁字斷為妄人所改，昔人不見易林善本，不知此為訛字。輙據此及安民呼池之語，以疑易林，豈知安為按、呼為湖之訛字也。《詩》&quot;差池其羽&quot;。</p><h3 id="蹇之艮" tabindex="-1">蹇之艮 <a class="header-anchor" href="#蹇之艮" aria-label="Permalink to “蹇之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>登山履谷，與虎相觸。蝟為功曹，班叔奔北，脫之喜國。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為山谷、為虎，震為登，坎為蝟，艮為官，故曰功曹。艮為叔，楚人謂虎為班，故曰班叔。《史記龜策傳》註：蝟能伏虎。故虎見而奔北。艮為國，震為脫、為喜，《論衛［當作衡］》雲&quot;人謂虎食人，功曹為姦所致也&quot;，其意以為功曹眾吏之率虎亦諸獸雄。</p><h3 id="蹇之漸" tabindex="-1">蹇之漸 <a class="header-anchor" href="#蹇之漸" aria-label="Permalink to “蹇之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>麟鳳所翔，國無咎殃。賈市十倍，復歸惠里。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為麟鳳，艮為國，巽為賈市、為利三倍，伏兌數十，故曰十倍。艮為室。</p><h3 id="蹇之歸妹" tabindex="-1">蹇之歸妹 <a class="header-anchor" href="#蹇之歸妹" aria-label="Permalink to “蹇之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>路險道難，水遏我前。進往不利，回車復還。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為道路，坎險故曰道難。坎為水，坎陷故，水遏我前。震為進，坎險故不利。震為車、為反，故曰復還。○遏，汲古訛過，依宋元本。</p><h3 id="蹇之豐" tabindex="-1">蹇之豐 <a class="header-anchor" href="#蹇之豐" aria-label="Permalink to “蹇之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>延頸望邑，思歸我室。臺榭不成，未得安息。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。艮為頸、為望、為邑，坎為室，震為歸，故曰思歸我室。艮為臺榭，巽隕落故不成，不得安息也。○我，宋元本作其，依汲古。艮為我也。</p><h3 id="蹇之旅" tabindex="-1">蹇之旅 <a class="header-anchor" href="#蹇之旅" aria-label="Permalink to “蹇之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>蒙生株瞿，棘掛我須。小人妬嫉，使恩不遂。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為蕃鮮，故曰蒙生。震為木故曰株，為草故曰瞿。《爾雅釋草》：&quot;大菊蘧麥&quot;註：即瞿麥藥草也。又《韓詩外傳》&quot;直曰車前，瞿曰芣苢&quot;。坎為棘，艮為須，坎在艮上，若須掛棘上也。艮為小，震為人，坎為妬嫉，故曰小人妬嫉。○須，汲古作須，非，依宋元本。蒙，蓋蔓生之屬，施於株瞿之上。</p><h3 id="蹇之巽" tabindex="-1">蹇之巽 <a class="header-anchor" href="#蹇之巽" aria-label="Permalink to “蹇之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>南至隱域，深潛處匿。聰明閉塞，與死為伍。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互離為南，巽伏故曰隱、曰潛、曰匿、曰閉塞。伏坎為聰，離為明，初至四大過死，故曰與死為伍。</p><h3 id="蹇之兌" tabindex="-1">蹇之兌 <a class="header-anchor" href="#蹇之兌" aria-label="Permalink to “蹇之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>機餌設張，司暴子良。範叔不廉，凶害及身。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。坎為機，震為餌、為張、為暴、為子，艮為司、為良，故曰司暴子良。《左傳》：&quot;鄭子良之父子孔為政也專，國人殺子孔，子良奔楚&quot;。互巽為蟲，故曰範，範，蠭也。《禮內則》&quot;爵鷃蜩範&quot;是也。艮為叔，故曰範叔。坎為凶害，艮為身。《史記》&quot;範睢從須賈使齊，齊王賜睢金牛酒歸，以此受折髂之辱&quot;。○首句元本作機設餌張，依汲古。司，汲古作計，依宋元本。</p><h3 id="蹇之渙" tabindex="-1">蹇之渙 <a class="header-anchor" href="#蹇之渙" aria-label="Permalink to “蹇之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>從騎出谷，游戲苦域。阪高不進，利無所得。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為騎、為出，艮為谷、為域，坎為苦，艮為阪、為高，巽為利，風散故無得。○谷，宋元本作門，苦域作空城，均依汲古。</p><h3 id="蹇之節" tabindex="-1">蹇之節 <a class="header-anchor" href="#蹇之節" aria-label="Permalink to “蹇之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>西國強梁，為虎作倀。東吞齊楚，並有其王。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>兌西艮國，震為健，故為強梁。強梁，多力也。艮為虎，坎為鬼，故曰倀。《本草》&quot;人死於虎則為倀鬼，導虎而行&quot;。震為楚，伏巽為齊，兌口為吞，震東，故曰東吞齊楚。震為王，言西秦併吞六王也。</p><h3 id="蹇之中孚" tabindex="-1">蹇之中孚 <a class="header-anchor" href="#蹇之中孚" aria-label="Permalink to “蹇之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>登山伐輻，虎在我側。王孫無懼，仁不見賊。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮山震登，艮為伐、為虎，巽為輻，故曰登山伐輻。震為王，艮為孫，故曰王孫。震為仁，巽伏故為賊。</p><h3 id="蹇之小過" tabindex="-1">蹇之小過 <a class="header-anchor" href="#蹇之小過" aria-label="Permalink to “蹇之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>六月騤騤，各欲有至。專徵束裝，俟時旦明。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>兌為月，震為反，故曰至。震為徵、為旦明，艮為時，艮止，故曰俟時旦明。《詩小雅》：&quot;六月棲棲，戎車既飭；四牡騤騤，載是常服。王於出征，以匡王國&quot;，載是常服，即束裝之事，言尹吉甫奉宣王命出征獫狁而治裝也。○首句依元刊，宋本、汲古作六目，非。至，依汲古，宋元本作望。束裝，宋、汲古本作未壯，依元本。第四句汲古作候待明旦，依宋元本。俟即待也，故知待為時之訛字。</p><h3 id="蹇之既濟" tabindex="-1">蹇之既濟 <a class="header-anchor" href="#蹇之既濟" aria-label="Permalink to “蹇之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>道陟多阪，牛馬蜿蟮。車不利載，請求不得。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>用半象，重艮故曰多阪。</p><h3 id="蹇之未濟" tabindex="-1">蹇之未濟 <a class="header-anchor" href="#蹇之未濟" aria-label="Permalink to “蹇之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>一口三舌，相妨無益。群羊百牂，不為威強。亡馬失駒，家耗於財。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>用半象，重兌故曰三舌，故曰群羊。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
